// Generated by src/build.mjs — makes the site installable and usable offline.
const CACHE = 'pdfmint-__VERSION__';
const CORE = __CORE__;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(CORE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('pdfmint-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);

  // Android share sheet → "Share to PDFMint"
  if (req.method === 'POST' && url.pathname === '/share-target/') {
    e.respondWith((async () => {
      const form = await req.formData();
      const files = form.getAll('files').filter((f) => f && f.size);
      await caches.delete('pdfm-shared');
      const c = await caches.open('pdfm-shared');
      await Promise.all(files.map((f, i) => c.put('/shared/' + i, new Response(f, {
        headers: { 'content-type': f.type || 'application/octet-stream', 'x-name': encodeURIComponent(f.name || 'file') }
      }))));
      const allPdf = files.length && files.every((f) => f.type === 'application/pdf' || /\.pdf$/i.test(f.name));
      return Response.redirect(allPdf ? '/merge-pdf/?shared=1' : '/image-to-pdf/?shared=1', 303);
    })());
    return;
  }

  if (req.method !== 'GET') return;
  const sameOrigin = url.origin === location.origin;
  const cdn = url.hostname === 'cdnjs.cloudflare.com' || url.hostname === 'cdn.jsdelivr.net' || url.hostname === 'fonts.gstatic.com' || url.hostname === 'fonts.googleapis.com';
  if (!sameOrigin && !cdn) return;

  if (req.mode === 'navigate') {
    // Network first so pages stay fresh; fall back to cache when offline.
    e.respondWith(
      fetch(req).then((res) => {
        const copy = res.clone();
        caches.open(CACHE).then((c) => c.put(req, copy));
        return res;
      }).catch(() => caches.match(req, { ignoreSearch: true }).then((r) => r || caches.match('/offline/')))
    );
    return;
  }

  e.respondWith(
    caches.match(req).then((hit) => hit || fetch(req).then((res) => {
      if (res.ok || res.type === 'opaque') {
        const copy = res.clone();
        caches.open(CACHE).then((c) => c.put(req, copy));
      }
      return res;
    }))
  );
});
